var TEXTOS = { es: ES, en: EN };
function t(lang, clave, vars) {
  const texto2 = (TEXTOS[lang] || EN)[clave] ?? EN[clave] ?? ES[clave] ?? clave;
  return vars ? texto2.replace(/\{(\w+)\}/g, (m, k) => vars[k] ?? m) : texto2;
}
function agregarTextos(es, en) {
  Object.assign(ES, es);
  Object.assign(EN, en || {});
}

